public Flux<EventRevision> history(String deviceId, String metric, Instant from, Instant to) {
    return client.sql("SELECT device_id, metric, t_device, revision, t_ingress, validation_status, raw_payload FROM telemetry.event_revisions WHERE device_id = :deviceId AND metric = :metric AND t_device >= :from AND t_device <= :to ORDER BY t_device, revision")
        .bind("deviceId", deviceId)
        .bind("metric", metric)
        .bind("from", from)
        .bind("to", to)
        .map((row, metadata) -> toRevision(row))
        .all();
}

public Mono<EventRevision> latest(String deviceId, String metric, Instant tDevice) {
    return client.sql("SELECT device_id, metric, t_device, revision, t_ingress, validation_status, raw_payload FROM telemetry.event_revisions WHERE device_id = :deviceId AND metric = :metric AND t_device = :tDevice ORDER BY revision DESC LIMIT 1")
        .bind("deviceId", deviceId)
        .bind("metric", metric)
        .bind("tDevice", tDevice)
        .map((row, metadata) -> toRevision(row))
        .first();
}

private static EventRevision toRevision(Row row) {
    return new EventRevision(
        row.get("device_id", String.class),
        row.get("metric", String.class),
        row.get("t_device", Instant.class),
        row.get("revision", Long.class),
        row.get("t_ingress", Instant.class),
        row.get("validation_status", String.class),
        row.get("raw_payload", String.class));
}
